<script setup lang="ts">import type{CascaderValue}from'@fex-design/core/cascader/types';import Button from'@fex-design/vue/ui/button';import{ref}from'vue';import{regionOptions}from'./data';import DemoCascader from'./demo-cascader.vue';import Demo from'./demo-section.vue';const value=ref<CascaderValue>(['zhejiang','hangzhou','xihu'])</script><template><Demo title="Controlled" description="External actions and Cascader share one path value."><DemoCascader :options="regionOptions" :value="value" @change="next=>value=next"/><div class="flex gap-space-md"><Button @click="value=['jiangsu','suzhou','industrial-park','loufeng']">Set Suzhou</Button><Button variant="outline" @click="value=undefined">Clear</Button></div><code>{{JSON.stringify(value)}}</code></Demo></template>
